}

echo "\n== MySQL limits ==\n";
foreach ($db->select(
    "SHOW VARIABLES WHERE Variable_name IN ('max_connections','wait_timeout','version','innodb_buffer_pool_size')"
) as $r) {
    echo str_pad($r['Variable_name'], 34) . $r['Value'] . PHP_EOL;
