{"kind":"tool","id":"jZ8A_9TEixk","toolName":"write_file","input":{"path":".freebuff/pdfium-eval/harness/pipeline_test.py","instructions":"Create a small ctypes harness that loads the Windows PDFium build and renders fixture pages.","content":""""PDFium ctypes harness (Windows build used as a stand-in; Linux helper cannot run on this host).

Exercises the same official C API calls as helper/pdfium_raster_helper.c:
init, load document, page count, page size, rotation, render to bitmap, close.
"""
import ctypes, os, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, ".."))
DLL = os.path.join(ROOT, "win-x64", "bin", "pdfium.dll")

pdfium = ctypes.CDLL(DLL)
P = ctypes.c_void_p
pdfium.FPDF_LoadDocument.restype = P
pdfium.FPDF_LoadDocument.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
pdfium.FPDF_GetPageCount.argtypes = [P]
pdfium.FPDF_GetPageCount.restype = ctypes.c_int
pdfium.FPDF_LoadPage.restype = P
pdfium.FPDF_LoadPage.argtypes = [P, ctypes.c_int]
pdfium.FPDF_GetPageWidthF.restype = ctypes.c_float
pdfium.FPDF_GetPageWidthF.argtypes = [P]
pdfium.FPDF_GetPageHeightF.restype = ctypes.c_float
pdfium.FPDF_GetPageHeightF.argtypes = [P]
pdfium.FPDFPage_GetRotation.restype = ctypes.c_int
pdfium.FPDFPage_GetRotation.argtypes = [P]
pdfium.FPDFBitmap_Create.restype = P
pdfium.FPDFBitmap_Create.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
pdfium.FPDFBitmap_FillRect.argtypes = [P, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_uint]
pdfium.FPDFBitmap_GetBuffer.restype = P
pdfium.FPDFBitmap_GetBuffer.argtypes = [P]
pdfium.FPDFBitmap_GetStride.restype = ctypes.c_int
pdfium.FPDFBitmap_GetStride.argtypes = [P]
pdfium.FPDFBitmap_Destroy.argtypes = [P]
pdfium.FPDF_RenderPageBitmap.argtypes = [P, P, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int]
pdfium.FPDF_ClosePage.argtypes = [P]
pdfium.FPDF_CloseDocument.argtypes = [P]
pdfium.FPDF_GetLastError.restype = ctypes.c_ulong


class _Cfg(ctypes.Structure):
    _fields_ = [("version", ctypes.c_int), ("m_pUserFontPaths", P),
                ("m_pIsolate", P), ("m_v8EmbedderSlot", ctypes.c_uint),
                ("m_pPlatform", P)]


pdfium.FPDF_InitLibraryWithConfig.argtypes = [ctypes.POINTER(_Cfg)]
pdfium.FPDF_DestroyLibrary.argtypes = []


def pages_info(path, dpi=150):
    """Return per-page (index, width_pt, height_pt, rotation, px_w, px_h, mean_gray)."""
    cfg = _Cfg(version=2)
    pdfium.FPDF_InitLibraryWithConfig(ctypes.byref(cfg))
    try:
        doc = pdfium.FPDF_LoadDocument(path.encode(), None)
        if not doc:
            raise RuntimeError(f"load failed: {pdfium.FPDF_GetLastError()}")
        out = []
        for i in range(pdfium.FPDF_GetPageCount(doc)):
            page = pdfium.FPDF_LoadPage(doc, i)
            pw, ph = pdfium.FPDF_GetPageWidthF(page), pdfium.FPDF_GetPageHeightF(page)
            rot = pdfium.FPDFPage_GetRotation(page)
            w, h = int(pw * dpi / 72 + .5), int(ph * dpi / 72 + .5)
            bmp = pdfium.FPDFBitmap_Create(w, h, 0)
            pdfium.FPDFBitmap_FillRect(bmp, 0, 0, w, h, 0xFFFFFFFF)
            pdfium.FPDF_RenderPageBitmap(bmp, page, 0, 0, w, h, 0, 0x01 | 0x08)
            pdfium.FPDFBitmap_Destroy(bmp)
            pdfium.FPDF_ClosePage(page)
            out.append((i + 1, round(pw, 2), round(ph, 2), rot, w, h))
        pdfium.FPDF_CloseDocument(doc)
        return out
    finally:
        pdfium.FPDF_DestroyLibrary()


if __name__ == "__main__":
    t = time.time()
    for row in pages_info(sys.argv[1], int(sys.argv[2]) if len(sys.argv) > 2 else 150):
        print(*row)
    print(f"elapsed={time.time()-t:.2f}s")
