+        double pw = FPDF_GetPageWidthF(page);
+        double ph = FPDF_GetPageHeightF(page);
+        int w = (int)(pw * dpi / 72.0 + 0.5);
+        int h = (int)(ph * dpi / 72.0 + 0.5);
+        int rot = FPDFPage_GetRotation(page);
+
+        FPDF_BITMAP bmp = FPDFBitmap_Create(w, h, 0);
+        if (!bmp) { FPDF_ClosePage(page); rc = 4; break; }
+        FPDFBitmap_FillRect(bmp, 0, 0, w, h, 0xFFFFFFFF);
+        FPDF_RenderPageBitmap(bmp, page, 0, 0, w, h, 0,
+                              FPDF_ANNOT | FPDF_LCD_TEXT);
+
+        unsigned char *buf = (unsigned char *)FPDFBitmap_GetBuffer(bmp);
+        int stride = FPDFBitmap_GetStride(bmp);
+        /* Convert BGRA (PDFium) -> RGB for P6 output. */
+        unsigned char *rgb = malloc((size_t)w * h * 3);
+        if (!rgb) { FPDFBitmap_Destroy(bmp); FPDF_ClosePage(page); rc = 4; break; }
+        for (int y = 0; y < h; y++) {
+            const unsigned char *src = buf + (size_t)y * stride;
+            unsigned char *dst = rgb + (size_t)y * w * 3;
+            for (int x = 0; x < w; x++) {
+                dst[x * 3 + 0] = src[x * 4 + 2];
+                dst[x * 3 + 1] = src[x * 4 + 1];
+                dst[x * 3 + 2] = src[x * 4 + 0];
+            }
+        }
+
+        char out_path[1024];
+        snprintf(out_path, sizeof(out_path), "%s/page-%04d.ppm", out_dir, i + 1);
+        if (!write_ppm(out_path, rgb, w, h)) rc = 4;
+        else fprintf(manifest, "%d %d %d %d %.2f %.2f\n", i + 1, w, h, rot, pw, ph);
+
+        free(rgb);
+        FPDFBitmap_Destroy(bmp);
+        FPDF_ClosePage(page);
+        if (rc) break;
+    }
+
